#pragma once
// Ephemeral TEST credentials generated by OpenSSL. Never a deployable key set.
#include "anaiero/infrastructure/native_tls.hpp"
#include <filesystem>
#include <memory>
#include <string>
#include <openssl/pem.h>
#include <openssl/x509v3.h>
namespace anaiero::mesh::test {
using Key=std::unique_ptr<EVP_PKEY,decltype(&EVP_PKEY_free)>;
using Certificate=std::unique_ptr<X509,decltype(&X509_free)>;
using Bio=std::unique_ptr<BIO,decltype(&BIO_free)>;
struct Credentials {
  tls::Configuration server,client,stranger,rotated_client;
  std::string server_pin,client_pin,stranger_pin,rotated_client_pin;
};
inline bool extension(X509* certificate,X509* issuer,int id,const char* value) {
  X509V3_CTX context{};X509V3_set_ctx(&context,issuer,certificate,nullptr,nullptr,0);
  X509_EXTENSION* item=X509V3_EXT_conf_nid(nullptr,&context,id,value);
  if(!item)return false;
  const bool success=X509_add_ext(certificate,item,-1)==1;X509_EXTENSION_free(item);return success;
}
inline Certificate certificate(EVP_PKEY* key,const char* name,long serial,
                              X509* issuer,EVP_PKEY* signer,bool authority) {
  Certificate cert(X509_new(),X509_free);
  if(!cert||X509_set_version(cert.get(),2)!=1||
     ASN1_INTEGER_set(X509_get_serialNumber(cert.get()),serial)!=1||
     !X509_gmtime_adj(X509_getm_notBefore(cert.get()),-3600)||
     !X509_gmtime_adj(X509_getm_notAfter(cert.get()),7*24*60*60)||
     X509_set_pubkey(cert.get(),key)!=1)return {nullptr,X509_free};
  X509_NAME* subject=X509_get_subject_name(cert.get());
  if(X509_NAME_add_entry_by_txt(subject,"CN",MBSTRING_ASC,
       reinterpret_cast<const unsigned char*>(name),-1,-1,0)!=1||
     X509_set_issuer_name(cert.get(),issuer?X509_get_subject_name(issuer):subject)!=1)
    return {nullptr,X509_free};
  if(!extension(cert.get(),issuer?issuer:cert.get(),NID_basic_constraints,
       authority?"critical,CA:TRUE,pathlen:1":"critical,CA:FALSE")||
     !extension(cert.get(),issuer?issuer:cert.get(),NID_key_usage,
       authority?"critical,keyCertSign,cRLSign":"critical,digitalSignature")||
     !extension(cert.get(),issuer?issuer:cert.get(),NID_subject_key_identifier,"hash"))
    return {nullptr,X509_free};
  if(!authority&&(!extension(cert.get(),issuer,NID_ext_key_usage,"serverAuth,clientAuth")||
     !extension(cert.get(),issuer,NID_subject_alt_name,"IP:127.0.0.1,IP:::1")))
    return {nullptr,X509_free};
  if(X509_sign(cert.get(),signer?signer:key,EVP_sha256())<=0)return {nullptr,X509_free};
  return cert;
}
inline bool write_certificate(const std::filesystem::path& path,X509* cert) {
  Bio bio(BIO_new_file(path.string().c_str(),"w"),BIO_free);
  return bio&&PEM_write_bio_X509(bio.get(),cert)==1;
}
inline bool write_key(const std::filesystem::path& path,EVP_PKEY* key) {
  Bio bio(BIO_new_file(path.string().c_str(),"w"),BIO_free);
  if(!bio||PEM_write_bio_PrivateKey(bio.get(),key,nullptr,nullptr,0,nullptr,nullptr)!=1)return false;
  std::error_code error;
  std::filesystem::permissions(path,std::filesystem::perms::owner_read|
    std::filesystem::perms::owner_write,std::filesystem::perm_options::replace,error);
  return !error;
}
inline bool create_credentials(const std::filesystem::path& directory,Credentials& output) {
  std::error_code error;std::filesystem::create_directories(directory,error);if(error)return false;
  Key ca_key(EVP_PKEY_Q_keygen(nullptr,nullptr,"EC","P-256"),EVP_PKEY_free);
  Key other_key(EVP_PKEY_Q_keygen(nullptr,nullptr,"EC","P-256"),EVP_PKEY_free);
  if(!ca_key||!other_key)return false;
  auto ca=certificate(ca_key.get(),"Anaiero ephemeral test CA",1,nullptr,nullptr,true);
  auto other=certificate(other_key.get(),"Anaiero untrusted test CA",2,nullptr,nullptr,true);
  if(!ca||!other||!write_certificate(directory/"ca.pem",ca.get())||
     !write_certificate(directory/"untrusted-ca.pem",other.get()))return false;
  auto leaf=[&](const char* name,long serial,X509* issuer,EVP_PKEY* signer,
                tls::Configuration& config,std::string& pin)->bool{
    Key key(EVP_PKEY_Q_keygen(nullptr,nullptr,"EC","P-256"),EVP_PKEY_free);
    if(!key)return false;
    auto cert=certificate(key.get(),name,serial,issuer,signer,false);
    if(!cert)return false;
    const auto cert_path=directory/(std::string(name)+".pem");
    const auto key_path=directory/(std::string(name)+"-key.pem");
    std::uint64_t expiry=0;
    if(!write_certificate(cert_path,cert.get())||!write_key(key_path,key.get())||
       !tls::detail::certificate_identity(cert.get(),pin,expiry))return false;
    config={cert_path.string(),key_path.string(),(directory/"ca.pem").string()};return true;
  };
  return leaf("server",3,ca.get(),ca_key.get(),output.server,output.server_pin)&&
    leaf("client",4,ca.get(),ca_key.get(),output.client,output.client_pin)&&
    leaf("stranger",5,other.get(),other_key.get(),output.stranger,output.stranger_pin)&&
    leaf("client-rotated",6,ca.get(),ca_key.get(),output.rotated_client,output.rotated_client_pin);
}
} // namespace anaiero::mesh::test
